/*
 * A086286  Smallest prime factor of 7-smooth numbers.
 * https://oeis.org/A086286
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = smallest prime factor of the n-th 7‑smooth number
 *            (numbers whose prime factors are only 2,3,5 or 7). The sequence
 *            is generated by the standard “Hamming numbers” algorithm with
 *            proper handling of duplicate candidates. The array of smooth
 *            numbers is stored in a separate array of type unsigne...
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdbool.h>
#include <stdlib.h>

static size_t max_computed = 0;          /* number of terms already built */
static size_t capacity   = 0;            /* allocated size of the arrays     */
static seq_t *spf_vals   = NULL;         /* smallest prime factor of each   */
static unsigned __int128 *smooth_vals = NULL;   /* smooth numbers themselves (64‑bit case) */
static seq_t *h_vals     = NULL;         /* smooth numbers when seq_t is big */

/* indices for the next candidate multiples */
static idx_t i2 = 0, i3 = 0, i5 = 0, i7 = 0;

static void ensure_capacity(size_t need)
{
    if (need <= capacity)
        return;
    size_t newcap = capacity ? capacity << 1 : 8;
    while (newcap < need)
        newcap <<= 1;
    capacity = newcap;

    /* allocate/resize smooth numbers array */
    if (smooth_vals) {
        smooth_vals = (unsigned __int128 *)realloc(smooth_vals, newcap * sizeof(unsigned __int128));
    } else {
        smooth_vals = (unsigned __int128 *)malloc(newcap * sizeof(unsigned __int128));
    }
    /* allocate/resize spf array */
    spf_vals = (seq_t *)realloc(spf_vals, newcap * sizeof(seq_t));

    /* For arbitrary‑precision seq_t we also keep h_vals for comparison
       (though it is only used when seq_t itself can hold the values). */
    if (h_vals) {
        h_vals = (seq_t *)realloc(h_vals, newcap * sizeof(seq_t));
    } else {
        h_vals = (seq_t *)malloc(newcap * sizeof(seq_t));
    }
}

static void init_sequence(void)
{
    if (max_computed > 0)
        return;
    ensure_capacity(1);
    smooth_vals[0] = (unsigned __int128)1;
    h_vals[0] = (seq_t)1;          /* for consistency with any seq_t size */
    spf_vals[0] = (seq_t)1;       /* 1 has no prime factor */
    max_computed = 1;
}

static void generate_upto(idx_t target)
{
    init_sequence();
    while ((idx_t)max_computed < target)
    {
        unsigned __int128 v2 = smooth_vals[i2] * (unsigned __int128)2;
        unsigned __int128 v3 = smooth_vals[i3] * (unsigned __int128)3;
        unsigned __int128 v5 = smooth_vals[i5] * (unsigned __int128)5;
        unsigned __int128 v7 = smooth_vals[i7] * (unsigned __int128)7;

        /* find the minimum */
        unsigned __int128 next = v2;
        if (v3 < next) next = v3;
        if (v5 < next) next = v5;
        if (v7 < next) next = v7;

        ENSURE_CAPACITY: /* helper label in case macros are used */
        ensure_capacity(max_computed + 1);

        smooth_vals[max_computed] = next;
        h_vals[max_computed] = (seq_t)next;  /* keep for comparison if needed */

        /* determine smallest prime factor among all primes that produce next */
        seq_t spf = (seq_t)7;     /* upper bound for correctness */

        if (v2 == next) {
            i2++; spf = (spf < (seq_t)2 ? spf : (seq_t)2);
        }
        if (v3 == next) {
            i3++; spf = (spf < (seq_t)3 ? spf : (seq_t)3);
        }
        if (v5 == next) {
            i5++; spf = (spf < (seq_t)5 ? spf : (seq_t)5);
        }
        if (v7 == next) {
            i7++; spf = (spf < (seq_t)7 ? spf : (seq_t)7);
        }

        spf_vals[max_computed] = spf;
        max_computed++;
    }
}

seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;           /* out of range, return 0 */
    generate_upto(n);
    return spf_vals[n-1];
}
